function lerNumero(): Promise<number> {
  // O retorno anotado dá contexto: isto é Promise<number>
  return new Promise((resolve) => setTimeout(() => resolve(42), 10));
}

function dobrarDepois(p: Promise<number>): Promise<number> {
  return p.then((n) => n * 2);
}

const pedido: Promise<number> = dobrarDepois(lerNumero());

// Com argumento de tipo explícito, resolve só aceita number
// @ts-expect-error TS2345: Argument of type 'string' is not assignable to parameter of type 'number | PromiseLike<number>'
const errada = new Promise<number>((resolve) => resolve("42"));

// Sem contexto nem argumento de tipo: Promise<unknown>
const semTipo = new Promise((resolve) => setTimeout(() => resolve(42), 10));
semTipo.then((valor) => {
  // @ts-expect-error TS18046: 'valor' is of type 'unknown'
  console.log(valor.toFixed(2));
});

async function contar(): Promise<number> {
  return 3; // o corpo devolve number, a função devolve Promise<number>
}

// Sem anotação a inferência dá o mesmo: () => Promise<string>
async function saudar() {
  return "olá";
}

// @ts-expect-error TS1064: The return type of an async function or method must be the global Promise<T> type
async function errada(): number {
  return 1;
}

function buscarNome(): Promise<string> {
  return new Promise((resolve) => setTimeout(() => resolve("Ana"), 10));
}

// Devolver uma promessa dentro de async não a embrulha outra vez
async function nomeDoServico() {
  return buscarNome();
}

const final: Promise<string> = nomeDoServico();
// @ts-expect-error TS2322: Type 'Promise<string>' is not assignable to type 'string'
const direto: string = nomeDoServico();

type Utilizador = { id: number; nome: string };

function obterUtilizador(id: number): Promise<Utilizador> {
  return new Promise((resolve) => setTimeout(() => resolve({ id, nome: "Ana" }), 10));
}

const promessa = obterUtilizador(1); // Promise<Utilizador>
const utilizador = await promessa;   // Utilizador
console.log(utilizador.nome);        // Ana

const cinco = await 5;               // number: await num valor simples devolve-o tal como está
console.log(cinco + 1);              // 6

async function maisUm(valor: number | Promise<number>): Promise<number> {
  const n = await valor; // number em ambos os casos
  return n + 1;
}
console.log(await maisUm(1), await maisUm(Promise.resolve(10))); // 2 11

type Dentro = Awaited<Promise<Promise<number>>>; // number
const d: Dentro = 7;
console.log(d); // 7

function atrasar<T>(valor: T, ms: number): Promise<T> {
  return new Promise((resolve) => setTimeout(() => resolve(valor), ms));
}

// Resultado: [string, number, boolean]
const [nome, idade, ativo] = await Promise.all([
  atrasar("Rita", 30),
  atrasar(28, 10),
  atrasar(true, 20),
]);
console.log(nome.toUpperCase(), idade + 1, ativo); // RITA 29 true

const lista = [atrasar(1, 10), atrasar(2, 20)]; // Promise<number>[]
const numeros = await Promise.all(lista);         // number[]
console.log(numeros); // [ 1, 2 ]

// string | number: qualquer uma pode chegar primeiro
const maisRapido = await Promise.race([atrasar("texto", 30), atrasar(99, 10)]);
console.log(maisRapido); // 99

// string: Promise.reject(...) é Promise<never> e não entra na união
const primeiroSucesso = await Promise.any([
  Promise.reject(new Error("falhou")),
  atrasar("ok", 10),
]);
console.log(primeiroSucesso); // ok

function tarefa(nome: string, ms: number, falhar: boolean): Promise<string> {
  return new Promise((resolve, reject) =>
    setTimeout(() => (falhar ? reject(new Error(`${nome} falhou`)) : resolve(`${nome} feita`)), ms),
  );
}

// [PromiseSettledResult<string>, PromiseSettledResult<string>, PromiseSettledResult<string>]
const resultados = await Promise.allSettled([
  tarefa("A", 20, false),
  tarefa("B", 10, true),
  tarefa("C", 30, false),
]);

for (const r of resultados) {
  if (r.status === "fulfilled") {
    console.log("ok:", r.value);             // r: PromiseFulfilledResult<string>
  } else {
    console.log("falha:", String(r.reason)); // r: PromiseRejectedResult
  }
}
// ok: A feita
// falha: Error: B falhou
// ok: C feita

type Encomenda = { id: number; total: number };

async function obterEncomenda(id: number): Promise<Encomenda> {
  return { id, total: 50 };
}

async function processar() {
  const encomenda = obterEncomenda(1); // falta o await: Promise<Encomenda>

  // @ts-expect-error TS2339: Property 'total' does not exist on type 'Promise<Encomenda>'
  console.log(encomenda.total);

  // @ts-expect-error TS2365: Operator '>' cannot be applied to types 'Promise<Encomenda>' and 'number'
  if (encomenda > 100) console.log("cara");

  // @ts-expect-error TS2801: This condition will always return true since this 'Promise<Encomenda>' is always defined
  if (encomenda) console.log("existe");

  // Promessa flutuante: compila sem erro, mas ninguém espera por ela
  obterEncomenda(2);

  const certa = await obterEncomenda(3); // Encomenda
  console.log(certa.total);
}

function esperar(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

type Tarefa = () => Promise<void>;

async function executarTodas(tarefas: Tarefa[]): Promise<void> {
  for (const t of tarefas) await t();
}

const registo: string[] = [];
const ids = [1, 2, 3];

// Aceite pelo compilador: o callback de forEach é (...) => void
ids.forEach(async (id) => {
  await esperar(10);
  registo.push(`forEach ${id}`);
});
console.log("depois do forEach:", registo.length); // depois do forEach: 0

await executarTodas(ids.map((id) => async () => {
  await esperar(20);
  registo.push(`em série ${id}`);
}));
console.log(registo);
// [ 'forEach 1', 'forEach 2', 'forEach 3', 'em série 1', 'em série 2', 'em série 3' ]

