function depois<T>(valor: T, ms: number): Promise<T> {
  return new Promise((resolve) => setTimeout(() => resolve(valor), ms));
}

const texto = await depois("pronto", 10); // string
const numero = await depois(7, 20);       // number
console.log(texto.toUpperCase(), numero * 2); // PRONTO 14

type Cliente = { id: number; nome: string };

function obterCliente(id: number): Promise<Cliente> {
  return new Promise((resolve) => setTimeout(() => resolve({ id, nome: "Marta" }), 20));
}

function obterPontos(id: number): Promise<number> {
  return new Promise((resolve) => setTimeout(() => resolve(id * 10), 10));
}

async function carregarResumo(id: number): Promise<string> {
  const [cliente, pontos] = await Promise.all([obterCliente(id), obterPontos(id)]);
  return `${cliente.nome} tem ${pontos} pontos`;
}

console.log(await carregarResumo(5)); // Marta tem 50 pontos

async function separar<T>(promessas: Promise<T>[]): Promise<{ valores: Awaited<T>[]; falhas: string[] }> {
  const resultados = await Promise.allSettled(promessas);
  const valores = resultados
    .filter((r): r is PromiseFulfilledResult<Awaited<T>> => r.status === "fulfilled")
    .map((r) => r.value);
  const falhas = resultados
    .filter((r): r is PromiseRejectedResult => r.status === "rejected")
    .map((r) => String(r.reason));
  return { valores, falhas };
}

const falhaSimulada = new Promise<number>((_, reject) =>
  setTimeout(() => reject(new Error("sem stock")), 10),
);

const resumo = await separar([Promise.resolve(1), falhaSimulada, Promise.resolve(3)]);
console.log(resumo.valores); // [ 1, 3 ]
console.log(resumo.falhas);  // [ 'Error: sem stock' ]

function atrasar<T>(valor: T, ms: number): Promise<T> {
  return new Promise((resolve) => setTimeout(() => resolve(valor), ms));
}

async function comLimite<T>(p: Promise<T>, ms: number, reserva: T): Promise<T> {
  let temporizador: ReturnType<typeof setTimeout> | undefined;
  const limite = new Promise<T>((resolve) => {
    temporizador = setTimeout(() => resolve(reserva), ms);
  });
  try {
    return await Promise.race([p, limite]);
  } finally {
    clearTimeout(temporizador);
  }
}

console.log(await comLimite(atrasar("rápida", 10), 40, "reserva")); // rápida
console.log(await comLimite(atrasar("lenta", 50), 20, "reserva"));  // reserva
